  "localModels.managed.coreBackendVariant": { type: "'auto' | 'cpu'", description: "Which build Atomic Core installs on Windows x64 (the `atomic-core` engine; `backendVariant` above is the llama-server engine's). - `\"auto\"` (default) — Core's recommendation for this hardware. - `\"cpu\"` — Core's CPU build." },
